import {sleepSounds,categories,presets} from './data.js';
import {read,write,remove,sessions,saveSession,notify,dateKey} from './storage.js';
import {validAnalysis} from './contract.js';
import {mountWindDown,stopWindDown} from './winddown.js';
import {mountSound,mountSleep,stopSound} from './sound.js';
const app=document.querySelector('#app');
const paths={moon:'<path d="M20.6 14A9 9 0 0 1 10 3.4 9 9 0 1 0 20.6 14Z"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',later:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',leaf:'<path d="M5 19C0 7 10 4 20 4c0 10-3 18-15 15Zm0 0L16 8"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',back:'<path d="m14 6-6 6 6 6"/>',play:'<path d="m9 5 10 7-10 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',sound:'<path d="M4 10v4m4-8v12m4-15v18m4-15v12m4-8v4"/>'};
export const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.moon}</svg>`;
export const state={session:null,draft:read('off:draft',''),screen:'tonight',aiStatus:'idle',audioStatus:'idle'};
if(typeof state.draft!=='string')state.draft='';
export const $=(selector)=>app.querySelector(selector);
export function intro(kicker,title,subtitle,mark='moon'){return `<section class="intro"><div class="moon-mark">${icon(mark)}</div><p class="eyebrow">${kicker}</p><h1 tabindex="-1">${title}</h1><p class="subtitle">${subtitle}</p></section>`;}
export function steps(n){return `<ol class="steps" aria-label="취침 준비 단계">${['생각 비우기','몸과 마음 쉬기','편안한 밤'].map((s,i)=>`<li class="${n===i+1?'current':''}" ${n===i+1?'aria-current="step"':''}><b>${i+1}</b>${s}</li>`).join('')}</ol>`;}
export function persist(){return saveSession(state.session);}
export function go(screen){stopWindDown();if(recognition){recognition.abort();recognition=null;}state.screen=screen;document.documentElement.style.setProperty('--bg',({tonight:'#111821',organize:'#0f151c',wind:'#0c1218',sound:'#090e13',sleep:'#080b0e'})[screen]||'#111821');document.querySelector('.site-header').hidden=screen==='sleep';document.querySelector('.site-footer').hidden=screen==='sleep';document.querySelector('#morning-link').disabled=screen==='loading';if(state.session&&['organize','wind','sound','sleep','safety'].includes(screen)){state.session.screen=screen;persist();}({tonight:renderTonight,loading:renderLoading,organize:renderOrganize,wind:()=>mountWindDown(app),sound:()=>mountSound(app),sleep:()=>mountSleep(app),morning:renderMorning,safety:renderSafety})[screen]();requestAnimationFrame(()=>{$('h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});}
let draftTimer,recognition;
function flushDraft(){clearTimeout(draftTimer);return write('off:draft',state.draft);}
window.addEventListener('pagehide',flushDraft);
document.addEventListener('visibilitychange',()=>{if(document.hidden)flushDraft();});
function renderTonight(){app.innerHTML=intro('A QUIET MOMENT FOR YOU','아직 마음에 남아 있는<br>생각이 있나요?','잘 정리하지 않아도 괜찮아요.<br>오늘의 생각을 여기에 잠시 내려놓으세요.')+`<form class="thought-form"><label class="sr-only" for="thought">마음에 남은 생각</label><div class="input-card"><textarea id="thought" maxlength="2000" placeholder="내일 해야 할 일, 자꾸 떠오르는 순간…&#10;무엇이든 적어보세요."></textarea><div class="input-footer"><span id="draft-state" class="draft-state" role="status">나만의 조용한 메모</span><span id="count"></span><button id="voice" type="button" class="voice-button" aria-label="음성으로 입력">${icon('mic')}</button></div></div><div id="ai-error"></div><button id="submit" class="primary-button" type="submit">생각 내려놓기</button><p class="privacy">${icon('lock')}작성한 생각은 이 기기에 보관돼요.<br>정리를 누르면 AI 분석을 위해 입력 내용이 전송돼요.</p></form>${steps(1)}`;
const input=$('#thought');input.value=state.draft;
const update=()=>{$('#count').textContent=`${input.value.length.toLocaleString()} / 2,000`;$('#submit').disabled=!input.value.trim();};update();
input.addEventListener('input',()=>{state.draft=input.value;update();$('#draft-state').textContent='작성 중';clearTimeout(draftTimer);draftTimer=setTimeout(()=>{const saved=flushDraft();if($('#draft-state'))$('#draft-state').textContent=saved?'이 기기에 저장됨':'저장하지 못했어요';},400);});
$('form').onsubmit=e=>{e.preventDefault();analyze();};$('#voice').onclick=startVoice;
}
function startVoice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){notify('이 브라우저에서는 음성 입력을 사용할 수 없어요. 글로 남겨주세요.');return;}if(recognition){recognition.stop();return;}recognition=new Speech();recognition.lang='ko-KR';recognition.interimResults=false;recognition.continuous=false;$('#voice').classList.add('active');$('#voice').setAttribute('aria-label','음성 입력 중지');notify('음성 인식은 브라우저 제공 서비스를 사용할 수 있어요.');recognition.onresult=e=>{const input=$('#thought');if(!input)return;input.value=(input.value+' '+e.results[0][0].transcript).trim().slice(0,2000);input.dispatchEvent(new Event('input'));};recognition.onerror=()=>notify('마이크를 사용할 수 없어요. 권한을 확인하거나 글로 남겨주세요.');recognition.onend=()=>{recognition=null;$('#voice')?.classList.remove('active');$('#voice')?.setAttribute('aria-label','음성으로 입력');};try{recognition.start();}catch{recognition=null;notify('음성 입력을 시작하지 못했어요.');}}
async function analyze(){if(state.aiStatus==='loading'||!state.draft.trim())return;flushDraft();if(/자살|죽고\s*싶|자해|목숨을|해치고\s*싶/.test(state.draft)){createSession({thoughts:[],tonightMessage:'',windDown:{type:'quiet',duration:0},safety:{flagged:true,type:'high_risk'}});go('safety');return;}state.aiStatus='loading';go('loading');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),20000);try{if(!navigator.onLine)throw new Error('offline');const response=await fetch('/api/thoughts/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:state.draft}),signal:controller.signal});if(!response.ok)throw new Error(response.status===429?'rate_limited':'server_error');const body=await response.json();if(!validAnalysis(body.data))throw new Error('invalid_response');state.aiStatus='success';createSession(body.data);state.session.demo=body.mode==='demo';persist();go(body.data.safety.flagged?'safety':'organize');}catch(error){state.aiStatus=error.name==='AbortError'?'timeout':error.message;go('tonight');$('#ai-error').innerHTML=`<div class="error-box" role="alert"><p>${state.aiStatus==='rate_limited'?'잠시 후 다시 정리해 주세요.':'지금은 생각을 정리할 수 없어요.'}<br>작성한 내용은 그대로 남아 있어요.</p><button type="button" id="fallback" class="secondary-button full">전체 내용을 내일 할 일로 저장</button></div>`;$('#fallback').onclick=()=>{createSession({thoughts:[{original:state.draft,summary:state.draft,category:'tomorrow'}],tonightMessage:'오늘의 생각을 이곳에 두고 쉬어요.',windDown:{type:'breathing',duration:180},safety:{flagged:false,type:null}});go('organize');};}finally{clearTimeout(timer);}}
function createSession(data){const id=crypto.randomUUID(),now=new Date().toISOString();state.session={id,createdAt:now,input:{text:state.draft},thoughts:data.thoughts.map(t=>({...t,id:crypto.randomUUID(),sessionId:id,completed:false,createdAt:now,completedAt:null})),tonightMessage:data.tonightMessage,safety:data.safety,windDown:{...data.windDown,completed:false,elapsed:0},sound:{id:sleepSounds.some(s=>s.id===read('off:last-sound'))?read('off:last-sound'):'sound-01',started:false,minutes:20},completedAt:null,morningFeedback:null,screen:'organize'};persist();}
function renderLoading(){app.innerHTML=`<div class="loader" aria-hidden="true"></div>${intro('LEAVE IT HERE','하나씩 정리하고 있어요.','생각은 잠시 여기에 맡겨두세요.')}<p class="small-note" role="status">생각 정리 중</p>`;}
function renderOrganize(){const s=state.session;app.innerHTML=`<button class="back" id="back">${icon('back')}다시 적기</button>${intro('A PLACE FOR EVERY THOUGHT','오늘은 여기 두고 가요.','분류나 문구를 바꿔도 괜찮아요.')}<div class="section-content" id="groups"></div><p id="message" class="small-note"></p><button id="confirm" class="primary-button">이렇게 남겨두고 쉬기</button>${steps(1)}`;$('#message').textContent=s.demo?'체험 모드 · AI 없이 간단한 규칙으로 나누었어요.':s.tonightMessage;
Object.entries(categories).forEach(([category,title],i)=>{const thoughts=s.thoughts.filter(t=>t.category===category);if(!thoughts.length)return;const group=document.createElement('section');group.className='thought-group';group.innerHTML=`<h2 class="group-title">${icon(['sun','later','leaf'][i])}${title}<small>${thoughts.length}개의 생각</small></h2>`;thoughts.forEach(t=>{const row=document.createElement('div');row.className='thought-row';const input=document.createElement('input');input.type='text';input.maxLength=2000;input.value=t.summary;input.setAttribute('aria-label','생각 문구 수정');input.oninput=()=>{t.summary=input.value;persist();};input.onblur=()=>{if(!t.summary.trim()){t.summary=t.original;input.value=t.summary;persist();}};row.append(input);const actions=document.createElement('div');actions.className='row-actions';const select=document.createElement('select');select.setAttribute('aria-label','생각 분류');Object.entries(categories).forEach(([key,label])=>select.add(new Option(label,key,false,key===category)));select.onchange=()=>{t.category=select.value;persist();renderOrganize();notify('생각을 옮겼어요.');};const del=document.createElement('button');del.className='icon-button';del.setAttribute('aria-label','생각 삭제');del.innerHTML=icon('trash');del.onclick=()=>{s.thoughts=s.thoughts.filter(x=>x.id!==t.id);persist();renderOrganize();};actions.append(select,del);row.append(actions);group.append(row);});$('#groups').append(group);});if(!s.thoughts.length)$('#groups').innerHTML='<p class="empty-state">남겨둘 생각이 없어도 괜찮아요.</p>';$('#back').onclick=()=>go('tonight');$('#confirm').onclick=()=>{if(persist()){state.draft='';remove('off:draft');go('wind');}};}
function renderSafety(){app.innerHTML=intro('YOU DON’T HAVE TO BE ALONE','지금은 혼자<br>견디지 않아도 괜찮아요.','잠들기보다, 곁의 도움을 먼저 받아보세요.')+`<p class="safety-copy">지금 스스로 또는 다른 사람을 해칠 위험이 있다면, 가까운 사람에게 함께 있어 달라고 부탁하고 지역 응급 서비스에 연락해 주세요.<br><br>작성한 내용은 그대로 남아 있어요.</p><button id="safety-back" class="secondary-button full">작성한 내용으로 돌아가기</button>`;$('#safety-back').onclick=()=>go('tonight');}
function renderMorning(){const all=sessions();const list=all.filter(s=>s.screen!=='safety');const thoughts=list.flatMap(s=>s.thoughts.filter(t=>t.category==='tomorrow').map(t=>({s,t})));app.innerHTML=intro('A NEW DAY, A LITTLE LIGHTER','좋은 아침이에요.','잠시 맡겨두었던 생각을 다시 꺼내볼까요?','sun')+`<div class="section-content" id="morning-items"></div><div id="morning-feedback"></div><button class="primary-button" id="new-night">오늘의 생각 남기기</button>`;if(!thoughts.length)$('#morning-items').innerHTML='<p class="empty-state">기다리고 있는 일이 없어요.<br>가볍게 오늘을 시작하세요.</p>';thoughts.forEach(({s,t})=>{const row=document.createElement('div');row.className='thought-row';const top=document.createElement('div');top.className='morning-item';const check=document.createElement('input');check.type='checkbox';check.id=`check-${t.id}`;check.checked=t.completed;const label=document.createElement('label');label.htmlFor=check.id;label.textContent=t.summary;check.onchange=()=>{t.completed=check.checked;t.completedAt=check.checked?new Date().toISOString():null;saveSession(s);};top.append(check,label);const actions=document.createElement('div');actions.className='row-actions';const later=document.createElement('button');later.className='text-button';later.textContent='나중으로 옮기기';later.onclick=()=>{t.category='later';saveSession(s);renderMorning();notify('나중에 생각할 일로 옮겼어요.');};const del=document.createElement('button');del.className='icon-button';del.setAttribute('aria-label','할 일 삭제');del.innerHTML=icon('trash');del.onclick=()=>{s.thoughts=s.thoughts.filter(x=>x.id!==t.id);saveSession(s);renderMorning();};actions.append(later,del);row.append(top,actions);$('#morning-items').append(row);});const last=[...list].reverse().find(s=>s.completedAt&&dateKey(s.createdAt)<dateKey());if(last){$('#morning-feedback').innerHTML='<hr class="divider"><p class="small-note">지난밤은 어땠나요?</p><div class="feedback"></div>';[['great','편안했어요'],['okay','괜찮았어요'],['rough','뒤척였어요']].forEach(([v,label])=>{const b=document.createElement('button');b.className=`secondary-button ${last.morningFeedback===v?'selected':''}`;b.textContent=label;b.setAttribute('aria-pressed',last.morningFeedback===v);b.onclick=()=>{last.morningFeedback=v;saveSession(last);renderMorning();};$('.feedback').append(b);});}$('#new-night').onclick=()=>{stopSound();state.session=null;remove('off:current');go('tonight');};}
document.querySelector('#morning-link').onclick=()=>{flushDraft();go('morning');};document.querySelector('.wordmark').onclick=e=>{e.preventDefault();if(state.aiStatus!=='loading'){flushDraft();stopSound();go('tonight');}};
const updateNetwork=()=>document.querySelector('#offline').hidden=navigator.onLine;window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);updateNetwork();
const saved=sessions();state.session=saved.find(s=>s.id===read('off:current'))||null;
const prior=saved.some(s=>dateKey(s.createdAt)<dateKey()&&(s.completedAt||s.thoughts.some(t=>t.category==='tomorrow')));
if(prior&&new Date().getHours()>=5&&new Date().getHours()<17)go('morning');else if(state.session&&dateKey(state.session.createdAt)===dateKey()&&['organize','wind','sound','sleep','safety'].includes(state.session.screen))go(state.session.screen);else go('tonight');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'stage_bedtime_thought',description:'Stage a bedtime draft locally. Does not send to AI or confirm a session.',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:2000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:({text})=>{if(typeof text!=='string'||!text.trim()||text.length>2000)throw new Error('1–2000 characters required');if(state.aiStatus==='loading')throw new Error('Analysis in progress');state.draft=text;const saved=flushDraft();go('tonight');return {staged:true,saved,characters:text.length};}})).catch(()=>{});}catch{}}
